import React, { useState, useMemo } from 'react';
import { Users, Layers, Target, Award, History, Crown, Calculator, Calendar, BarChart3, TrendingUp } from 'lucide-react';
import { AnalysisState } from '../types';
import { StatCard, TabButton } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';
import { useTranslation } from '../context/LanguageContext';

// View Imports
import SchoolView from './SchoolView';
import ClassComparisonView from './ClassComparisonView';
import EliteBenchmarksView from './EliteBenchmarksView';
import ExamParametersView from './ExamParametersView';
import StudentDetailView from './StudentDetailView';
import SubjectAnalysisView from './SubjectAnalysisView';
import ProgressAnalysisView from './ProgressAnalysisView';

const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'];

const Dashboard: React.FC<{ data: AnalysisState }> = ({ data }) => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState<'school' | 'comparison' | 'kings' | 'subjectAnalysis' | 'parameters' | 'student' | 'progress'>('school');

  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );

  const [selectedPeriod, setSelectedPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [selectedClasses, setSelectedClasses] = useState<string[]>([data.classes[0]]);
  const [benchmarkClass, setBenchmarkClass] = useState(data.classes[0]);
  const [selectedStudentId, setSelectedStudentId] = useState(data.students[0]?.id);

  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [classFilter, setClassFilter] = useState<string>('all');

  // 新增：班级对比专用的动态阈值状态
  const [comparisonThresholds, setComparisonThresholds] = useState<number[]>([50, 100, 200, 250, 400]);

  const [thresholdType, setThresholdType] = useState<'rank' | 'percent'>('rank');
  const [manualThresholds, setManualThresholds] = useState<Record<string, number>>({
    '清北': 5, 'C9': 30, '高分数': 100, '名校': 300, '特控': 600,
  });

  const allHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateHistoricalRanks(data.students), 
    [data.students]
  );

  const allClassHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateClassHistoricalRanks(data.students), 
    [data.students]
  );

  const allSubjectRanks = useMemo(() => 
    AnalysisEngine.calculateSubjectHistoricalRanks(data.students, data.subjects),
    [data.students, data.subjects]
  );

  const gradeAveragesByPeriod = useMemo(() => 
    AnalysisEngine.calculateGradeAverages(data.students), 
    [data.students]
  );

  const periodData = useMemo(() => 
    AnalysisEngine.getPeriodSnapshot(data.students, selectedPeriod, allHistoricalRanks),
    [data.students, selectedPeriod, allHistoricalRanks]
  );

  const hasImportedStatus = useMemo(() => 
    periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== ''),
    [periodData]
  );

  const admissionLabels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const thresholds = useMemo(() => {
    if (hasImportedStatus) {
      return AnalysisEngine.deriveThresholdsFromMetadata(periodData, admissionLabels);
    }
    return manualThresholds;
  }, [hasImportedStatus, periodData, manualThresholds]);

  const effectiveThresholdType = hasImportedStatus ? 'percent' : thresholdType;

  const examParameters = useMemo(() => 
    AnalysisEngine.calculateExamParameters(periodData, data.subjects),
    [periodData, data.subjects]
  );

  const aboveLineCount = useMemo(() => {
    if (hasImportedStatus) {
      const validLabels = ['清北', 'C9', '高分', '名校', '特控', '上线', '一本', '本科'];
      return periodData.filter(s => {
        const status = s.currentStatus || '';
        return status !== '' && status !== '未上线' && validLabels.some(label => status.includes(label));
      }).length;
    }
    const limit = effectiveThresholdType === 'rank' ? (thresholds['特控'] || 0) : Math.round(((thresholds['特控'] || 0) / 100) * periodData.length);
    return periodData.filter(s => s.periodSchoolRank <= limit).length;
  }, [periodData, thresholds, effectiveThresholdType, hasImportedStatus]);

  const classComparisonData = useMemo(() => data.subjects.map(sub => {
    const entry: any = { name: sub };
    selectedClasses.forEach(cls => {
      const clsStudents = periodData.filter(s => s.class === cls);
      entry[cls] = clsStudents.length > 0 ? parseFloat((clsStudents.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / clsStudents.length).toFixed(2)) : 0;
    });
    return entry;
  }), [periodData, data.subjects, selectedClasses]);

  // 更新：使用动态阈值计算名次分布
  const rankingDistributionData = useMemo(() => 
    comparisonThresholds.sort((a, b) => a - b).map(bucket => {
      const entry: any = { name: `Top ${bucket}`, limit: bucket };
      selectedClasses.forEach(cls => { 
        entry[cls] = periodData.filter(s => s.class === cls && s.periodSchoolRank <= bucket).length; 
      });
      return entry;
    }), [periodData, selectedClasses, comparisonThresholds]);

  const kingsData = useMemo(() => data.subjects.map(sub => ({
    subject: sub,
    classMax: Math.max(...periodData.filter(s => s.class === benchmarkClass).map(s => s.currentScores[sub] || 0), 0),
    gradeMax: Math.max(...periodData.map(s => s.currentScores[sub] || 0), 0)
  })), [periodData, data.subjects, benchmarkClass]);

  const duelData = useMemo(() => {
    const classFirst = periodData.filter(s => s.class === benchmarkClass).sort((a,b) => b.currentTotal - a.currentTotal)[0];
    const schoolFirst = periodData[0];
    return data.subjects.map(sub => ({ subject: sub, classFirst: classFirst?.currentScores[sub] || 0, schoolFirst: schoolFirst?.currentScores[sub] || 0 }));
  }, [periodData, data.subjects, benchmarkClass]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard icon={<Users className="w-5 h-5 text-blue-600" />} title={t('stat.total_students')} value={data.students.length.toString()} subtitle="Cohort Size" />
        <StatCard icon={<Layers className="w-5 h-5 text-green-600" />} title={t('stat.classes')} value={data.classes.length.toString()} subtitle="Groups" />
        <StatCard icon={<Target className="w-5 h-5 text-purple-600" />} title={t('stat.above_line')} value={aboveLineCount.toString()} subtitle={selectedPeriod} />
        <StatCard icon={<Award className="w-5 h-5 text-orange-600" />} title={t('stat.best_score')} value={data.schoolStats.max.toString()} subtitle="School Record" />
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-1 bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100 w-fit">
          <TabButton active={activeTab === 'school'} onClick={() => setActiveTab('school')} icon={<History className="w-4 h-4"/>} label={t('tab.school')} />
          <TabButton active={activeTab === 'comparison'} onClick={() => setActiveTab('comparison')} icon={<Layers className="w-4 h-4"/>} label={t('tab.comparison')} />
          <TabButton active={activeTab === 'kings'} onClick={() => setActiveTab('kings')} icon={<Crown className="w-4 h-4"/>} label={t('tab.kings')} />
          <TabButton active={activeTab === 'parameters'} onClick={() => setActiveTab('parameters')} icon={<Calculator className="w-4 h-4"/>} label={t('tab.parameters')} />
          <TabButton active={activeTab === 'subjectAnalysis'} onClick={() => setActiveTab('subjectAnalysis')} icon={<BarChart3 className="w-4 h-4"/>} label={t('tab.subject')} />
          <TabButton active={activeTab === 'progress'} onClick={() => setActiveTab('progress')} icon={<TrendingUp className="w-4 h-4"/>} label={t('tab.progress')} />
          <TabButton active={activeTab === 'student'} onClick={() => setActiveTab('student')} icon={<Target className="w-4 h-4"/>} label={t('tab.student')} />
        </div>
        <div className="flex items-center gap-3 bg-blue-50/50 px-4 py-2 rounded-2xl border border-blue-100">
          <Calendar className="w-4 h-4 text-blue-600" />
          <select className="bg-transparent border-none text-sm font-black text-blue-900 focus:ring-0 cursor-pointer" value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)}>
            {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div className="w-full">
        {activeTab === 'school' && <SchoolView selectedPeriod={selectedPeriod} periodData={periodData} subjects={data.subjects} thresholds={thresholds} setThresholds={setManualThresholds} thresholdType={effectiveThresholdType} setThresholdType={setThresholdType} hasImportedStatus={hasImportedStatus} totalStudents={data.students.length} />}
        {activeTab === 'comparison' && (
          <ClassComparisonView 
            selectedPeriod={selectedPeriod} 
            classes={data.classes} 
            selectedClasses={selectedClasses} 
            setSelectedClasses={setSelectedClasses} 
            classComparisonData={classComparisonData} 
            rankingDistributionData={rankingDistributionData} 
            colors={colors} 
            periodData={periodData} 
            thresholds={comparisonThresholds}
            setThresholds={setComparisonThresholds}
          />
        )}
        {activeTab === 'kings' && <EliteBenchmarksView selectedPeriod={selectedPeriod} classes={data.classes} benchmarkClass={benchmarkClass} setBenchmarkClass={setBenchmarkClass} kingsData={kingsData} duelData={duelData} />}
        {activeTab === 'parameters' && <ExamParametersView selectedPeriod={selectedPeriod} examParameters={examParameters} colors={colors} totalParticipants={periodData.length} />}
        {activeTab === 'subjectAnalysis' && (
          <SubjectAnalysisView 
            selectedPeriod={selectedPeriod}
            periodData={periodData}
            subjects={data.subjects}
            classes={data.classes}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
            totalStudents={data.students.length}
          />
        )}
        {activeTab === 'progress' && (
          <ProgressAnalysisView 
            students={data.students}
            allPeriods={allPeriods}
            allHistoricalRanks={allHistoricalRanks}
            classes={data.classes}
          />
        )}
        {activeTab === 'student' && (
          <StudentDetailView 
            studentSearchTerm={studentSearchTerm} setStudentSearchTerm={setStudentSearchTerm} 
            classFilter={classFilter} setClassFilter={setClassFilter} classes={data.classes} 
            selectableStudents={data.students.filter(s => s.name.toLowerCase().includes(studentSearchTerm.toLowerCase()) && (classFilter === 'all' || s.class === classFilter))} 
            selectedStudentId={selectedStudentId} setSelectedStudentId={setSelectedStudentId} 
            selectedStudent={data.students.find(s => s.id === selectedStudentId)} 
            subjects={data.subjects} gradeAveragesByPeriod={gradeAveragesByPeriod} 
            allHistoricalRanks={allHistoricalRanks}
            allClassHistoricalRanks={allClassHistoricalRanks}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
            totalStudents={data.students.length}
            selectedPeriod={selectedPeriod}
            periodData={periodData}
          />
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useMemo, useState } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { Trophy, BarChart2, Star, TrendingUp, Zap, Users, PieChart as PieIcon, Plus, X, Settings2 } from 'lucide-react';
import { ChartContainer, FilterChip } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';
import { useTranslation } from '../context/LanguageContext';

interface ClassComparisonViewProps {
  selectedPeriod: string;
  classes: string[];
  selectedClasses: string[];
  setSelectedClasses: React.Dispatch<React.SetStateAction<string[]>>;
  classComparisonData: any[];
  rankingDistributionData: any[];
  colors: string[];
  periodData: any[];
  thresholds: number[];
  setThresholds: React.Dispatch<React.SetStateAction<number[]>>;
}

const ClassComparisonView: React.FC<ClassComparisonViewProps> = ({ 
  selectedPeriod, classes, selectedClasses, setSelectedClasses, classComparisonData, rankingDistributionData, colors, periodData, thresholds, setThresholds 
}) => {
  const { t } = useTranslation();
  const [newThreshold, setNewThreshold] = useState<string>('');

  const classSummaries = useMemo(() => 
    AnalysisEngine.getClassSummaries(periodData, selectedClasses),
    [selectedClasses, periodData]
  );

  const leaderboard = useMemo(() => 
    AnalysisEngine.getClassLeaderboard(classSummaries),
    [classSummaries]
  );

  const rowMaxMap = useMemo(() => 
    AnalysisEngine.calculateHeatmapMaxValues(classComparisonData, selectedClasses),
    [classComparisonData, selectedClasses]
  );

  const distRowMaxMap = useMemo(() => 
    AnalysisEngine.calculateHeatmapMaxValues(rankingDistributionData, selectedClasses),
    [rankingDistributionData, selectedClasses]
  );

  // 动态生成阈值色阶
  const tierColors = useMemo(() => {
    const base = ['#be123c', '#1e40af', '#0369a1', '#0d9488', '#10b981', '#8b5cf6', '#d946ef'];
    const result = thresholds.map((_, i) => base[i % base.length]);
    result.push('#94a3b8'); // 其他
    return result;
  }, [thresholds]);

  const populationDistData = useMemo(() => {
    const sortedThresholds = [...thresholds].sort((a, b) => a - b);
    return selectedClasses.map(cls => {
      const clsStudents = periodData.filter(s => s.class === cls);
      const totalCount = clsStudents.length;
      if (totalCount === 0) return { className: cls, data: [] };

      const data = sortedThresholds.map((limit, idx) => {
        const prevLimit = idx === 0 ? 0 : sortedThresholds[idx - 1];
        const count = clsStudents.filter(s => s.periodSchoolRank > prevLimit && s.periodSchoolRank <= limit).length;
        return { name: `Top ${limit}`, value: count, color: tierColors[idx] };
      });

      const handledCount = data.reduce((acc, d) => acc + d.value, 0);
      data.push({
        name: t('comparison.tier_others'),
        value: Math.max(0, totalCount - handledCount),
        color: tierColors[tierColors.length - 1]
      });

      return { className: cls, data: data.filter(d => d.value >= 0) };
    });
  }, [selectedClasses, periodData, t, thresholds, tierColors]);

  const handleAddThreshold = () => {
    const val = parseInt(newThreshold);
    if (!isNaN(val) && val > 0 && !thresholds.includes(val)) {
      setThresholds(prev => [...prev, val].sort((a, b) => a - b));
      setNewThreshold('');
    }
  };

  const removeThreshold = (val: number) => {
    setThresholds(prev => prev.filter(t => t !== val));
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col gap-6">
        <div className="flex flex-col md:flex-row justify-between gap-4">
          <div>
            <h2 className="text-xl font-black text-gray-900">{t('comparison.title')}</h2>
            <p className="text-xs text-gray-500 mt-1">{t('comparison.desc')}</p>
          </div>
          <div className="flex flex-wrap gap-2">
            {classes.map(cls => (
              <FilterChip 
                key={cls}
                label={cls}
                active={selectedClasses.includes(cls)}
                onClick={() => setSelectedClasses(prev => prev.includes(cls) ? prev.filter(p => p !== cls) : [...prev, cls])}
                color="blue"
              />
            ))}
          </div>
        </div>

        {/* 动态阈值配置面板 */}
        <div className="pt-4 border-t border-gray-50 space-y-3">
          <div className="flex items-center gap-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">
            <Settings2 className="w-3.5 h-3.5 text-blue-500" />
            配置统计名次段 (阈值)
          </div>
          <div className="flex flex-wrap items-center gap-2">
            {thresholds.sort((a,b)=>a-b).map(val => (
              <div key={val} className="flex items-center gap-1.5 bg-gray-50 border border-gray-200 pl-3 pr-1 py-1.5 rounded-xl transition-all hover:border-blue-300">
                <span className="text-xs font-black text-gray-700">Top {val}</span>
                <button onClick={() => removeThreshold(val)} className="p-1 hover:bg-red-50 hover:text-red-500 rounded-lg text-gray-300 transition-colors">
                  <X className="w-3.5 h-3.5" />
                </button>
              </div>
            ))}
            <div className="flex items-center gap-2 ml-2">
              <input 
                type="number" 
                value={newThreshold}
                onChange={(e) => setNewThreshold(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleAddThreshold()}
                placeholder="新增阈值"
                className="w-24 bg-gray-50 border border-gray-100 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-blue-500 transition-all"
              />
              <button 
                onClick={handleAddThreshold}
                className="p-1.5 bg-blue-600 text-white rounded-xl shadow-md hover:bg-blue-700 active:scale-95 transition-all"
              >
                <Plus className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {leaderboard && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-gradient-to-br from-amber-50 to-orange-100 p-6 rounded-3xl border border-amber-200 shadow-sm relative overflow-hidden group">
            <Star className="w-20 h-20 text-amber-200/50 absolute -right-4 -bottom-4 rotate-12 group-hover:scale-110 transition-transform" />
            <h4 className="text-[10px] font-black text-amber-700 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Trophy className="w-3 h-3" /> {t('comparison.stat_highest_avg')}
            </h4>
            <p className={`font-black text-amber-900 leading-tight ${leaderboard.highestAvg.className.length > 8 ? 'text-xl' : 'text-3xl'}`}>{leaderboard.highestAvg.className}</p>
            <p className="text-sm font-bold text-amber-700 mt-1">{leaderboard.highestAvg.average} {t('comparison.stat_points_avg')}</p>
          </div>

          <div className="bg-gradient-to-br from-indigo-50 to-blue-100 p-6 rounded-3xl border border-indigo-200 shadow-sm relative overflow-hidden group">
            <Zap className="w-20 h-20 text-indigo-200/50 absolute -right-4 -bottom-4 rotate-12 group-hover:scale-110 transition-transform" />
            <h4 className="text-[10px] font-black text-indigo-700 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Star className="w-3 h-3" /> {t('comparison.stat_most_top10')}
            </h4>
            <p className={`font-black text-indigo-900 leading-tight ${leaderboard.mostTop10.className.length > 8 ? 'text-xl' : 'text-3xl'}`}>{leaderboard.mostTop10.className}</p>
            <p className="text-sm font-bold text-indigo-700 mt-1">{leaderboard.mostTop10.top10} {t('comparison.stat_students_top10')}</p>
          </div>

          <div className="bg-gradient-to-br from-emerald-50 to-teal-100 p-6 rounded-3xl border border-emerald-200 shadow-sm relative overflow-hidden group">
            <TrendingUp className="w-20 h-20 text-emerald-200/50 absolute -right-4 -bottom-4 rotate-12 group-hover:scale-110 transition-transform" />
            <h4 className="text-[10px] font-black text-emerald-700 uppercase tracking-widest mb-4 flex items-center gap-2">
              <Users className="w-3 h-3" /> {t('comparison.stat_strongest_bench')}
            </h4>
            <p className={`font-black text-emerald-900 leading-tight ${leaderboard.mostTop50.className.length > 8 ? 'text-xl' : 'text-3xl'}`}>{leaderboard.mostTop50.className}</p>
            <p className="text-sm font-bold text-emerald-700 mt-1">{leaderboard.mostTop50.top50} {t('comparison.stat_students_top50')}</p>
          </div>
        </div>
      )}

      {/* Population Distribution Donut Charts */}
      <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm">
        <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-8 flex items-center gap-2">
          <PieIcon className="w-4 h-4 text-indigo-500" /> {t('comparison.chart_population_dist')}
        </h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {populationDistData.map((clsData, idx) => (
            <div key={clsData.className} className="flex flex-col items-center p-4 bg-gray-50/50 rounded-2xl border border-gray-100 hover:border-indigo-200 transition-all">
              <h4 className="text-sm font-black text-gray-800 mb-2">{clsData.className}</h4>
              <div className="h-[200px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={clsData.data}
                      cx="50%"
                      cy="50%"
                      innerRadius={50}
                      outerRadius={70}
                      paddingAngle={4}
                      dataKey="value"
                    >
                      {clsData.data.map((entry: any, index: number) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
                      formatter={(value: number) => [`${value} ${t('comparison.count')}`, '']}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>
              <div className="mt-2 grid grid-cols-2 gap-x-4 gap-y-1 w-full px-2">
                {clsData.data.map((d, i) => (
                  <div key={i} className="flex items-center gap-1.5 text-[10px] text-gray-500 truncate">
                    <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: d.color }} />
                    <span className="truncate">{d.name}</span>
                    <span className="font-bold ml-auto">{d.value}</span>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-gray-100 shadow-lg overflow-hidden">
        <div className="px-8 py-6 bg-gray-900 text-white flex items-center justify-between">
          <div>
            <h3 className="text-xs font-black uppercase tracking-widest flex items-center gap-2">
              <BarChart2 className="w-4 h-4 text-blue-400" /> {t('comparison.matrix_title')}
            </h3>
            <p className="text-[10px] opacity-60 mt-1">{t('comparison.matrix_desc')}</p>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-8 py-6 text-xs font-black text-gray-400 uppercase tracking-widest border-r border-gray-100 min-w-[180px]">{t('comparison.matrix_header')}</th>
                {selectedClasses.map((cls, idx) => (
                  <th key={cls} className="px-8 py-6 text-center border-r border-gray-100 min-w-[160px]">
                    <div className="inline-flex items-center justify-center w-8 h-8 rounded-lg mb-2 text-white font-black" style={{ backgroundColor: colors[idx % colors.length] }}>
                      {idx + 1}
                    </div>
                    <div className="text-lg font-black text-gray-900">{cls}</div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              <tr className="bg-blue-50/10">
                <td className="px-8 py-5 font-black text-blue-600 flex items-center gap-2">
                  <Trophy className="w-4 h-4" /> {t('comparison.matrix_total_avg')}
                </td>
                {classSummaries.map((s, idx) => {
                  const isMax = s.average === leaderboard?.highestAvg.average;
                  return (
                    <td key={idx} className={`px-8 py-5 text-center transition-all ${isMax ? 'bg-amber-50 font-black text-amber-700' : 'text-gray-600 font-bold'}`}>
                      {s.average}
                      {isMax && <Star className="w-3 h-3 inline ml-1 fill-current" />}
                    </td>
                  );
                })}
              </tr>

              <tr className="bg-gray-50/30">
                <td colSpan={selectedClasses.length + 1} className="px-8 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">{t('comparison.matrix_subject_avg')}</td>
              </tr>

              {classComparisonData.map((row, rowIdx) => (
                <tr key={rowIdx} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-8 py-4 text-gray-700 font-bold">{row.name}</td>
                  {selectedClasses.map((cls, colIdx) => {
                    const val = row[cls] || 0;
                    const isMax = val === rowMaxMap[row.name] && val > 0;
                    return (
                      <td key={colIdx} className={`px-8 py-4 text-center transition-all ${isMax ? 'bg-emerald-50 text-emerald-700 font-black' : 'text-gray-600'}`}>
                        {val || '-'}
                      </td>
                    );
                  })}
                </tr>
              ))}

              <tr className="bg-gray-50/30">
                <td colSpan={selectedClasses.length + 1} className="px-8 py-2 text-[10px] font-black text-gray-400 uppercase tracking-widest">{t('comparison.matrix_rank_dist')}</td>
              </tr>

              {rankingDistributionData.map((row, rowIdx) => (
                <tr key={rowIdx} className="hover:bg-gray-50/50 transition-colors">
                  <td className="px-8 py-4 text-gray-600 font-medium">{row.name} {t('comparison.count')}</td>
                  {selectedClasses.map((cls, colIdx) => {
                    const val = row[cls] || 0;
                    const isMax = val === distRowMaxMap[row.name] && val > 0;
                    return (
                      <td key={colIdx} className={`px-8 py-4 text-center ${isMax ? 'bg-indigo-50 text-indigo-700 font-black' : 'text-gray-500'}`}>
                        <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold ${isMax ? 'bg-indigo-100' : 'bg-gray-100'}`}>
                          {val}
                        </span>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <ChartContainer title={t('comparison.chart_gap')}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={classComparisonData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={11} fontWeight="bold" />
              <YAxis stroke="#94a3b8" fontSize={11} />
              <Tooltip 
                cursor={{fill: '#f8fafc'}} 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }} 
              />
              <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '20px' }} />
              {selectedClasses.map((cls, idx) => (
                <Bar 
                  key={cls} 
                  dataKey={cls} 
                  fill={colors[idx % colors.length]} 
                  radius={[6, 6, 0, 0]} 
                  barSize={selectedClasses.length > 3 ? 15 : 30}
                />
              ))}
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>

        <ChartContainer title={t('comparison.chart_density')}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={rankingDistributionData} margin={{ top: 20, right: 30, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={11} fontWeight="bold" />
              <YAxis stroke="#94a3b8" fontSize={11} />
              <Tooltip 
                cursor={{fill: '#f8fafc'}} 
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' }} 
              />
              <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '20px' }} />
              {selectedClasses.map((cls, idx) => (
                <Bar 
                  key={cls} 
                  dataKey={cls} 
                  fill={colors[idx % colors.length]} 
                  radius={[6, 6, 0, 0]}
                  barSize={selectedClasses.length > 3 ? 15 : 30}
                />
              ))}
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>
      </div>
    </div>
  );
};

